topic(["islam","general","d-av-sonstiges-islam-2","c-allahs-thron-knirchen"],{"title":"Allahs thron knirchen","k":"Averroes","blurb":"1 post","article":{"claim":"Allahs thron knirchen","tree":{"they":"Allahs thron knirchen","we":"Abdullah ist unbekannt","more":{"h":"Allahs thron knirchen","p":["Abdullah ist unbekannt"],"imgs":18,"credit":"Averroes · sonstiges islam 2 › #allahs-thron-knirchen","link":"https://discord.com/channels/1275832106949283962/1280975859079188511"},"next":[]},"sum":"Notes from Averroes (sonstiges islam 2 › #allahs-thron-knirchen)."}});
